using FamilyVeda.Application.Portal;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;

namespace FamilyVeda.Api.Controllers;

[Route("api/v1")]
[Authorize(Policy = "FamilyUser")]
public sealed class JoinRequestsController(IJoinRequestService joinRequestService) : ApiControllerBase
{
    [HttpPost("families/join-requests")]
    [EnableRateLimiting("FamilyCode")]
    public async Task<ActionResult<JoinRequestDto>> Create(CreateJoinRequest request, CancellationToken cancellationToken)
    {
        var result = await joinRequestService.CreateAsync(request, cancellationToken);
        return Created($"/api/v1/families/join-requests/{result.Id}", result);
    }

    [HttpGet("families/{familyId:guid}/join-requests")]
    public async Task<ActionResult<IReadOnlyList<JoinRequestDto>>> GetForFamily(Guid familyId, string? status, CancellationToken cancellationToken) =>
        Ok(await joinRequestService.GetForFamilyAsync(familyId, status, cancellationToken));

    [HttpGet("families/join-requests/mine")]
    public async Task<ActionResult<IReadOnlyList<JoinRequestDto>>> GetMine(CancellationToken cancellationToken) =>
        Ok(await joinRequestService.GetMineAsync(cancellationToken));

    [HttpPost("families/join-requests/{id:guid}/accept")]
    public async Task<ActionResult<JoinRequestDto>> Accept(Guid id, CancellationToken cancellationToken) =>
        Ok(await joinRequestService.AcceptAsync(id, cancellationToken));

    [HttpPost("families/join-requests/{id:guid}/decline")]
    public async Task<ActionResult<JoinRequestDto>> Decline(Guid id, CancellationToken cancellationToken) =>
        Ok(await joinRequestService.DeclineAsync(id, cancellationToken));
}
